do $$begin if exists(select 1 from public.profiles where email not like '%@local.invalid') then raise exception 'LOCAL_FIXTURE_REQUIRED';end if;end$$;
do $$declare cfo uuid;sup uuid;banker uuid;account uuid;payment uuid;preview jsonb;claim jsonb;duplicate jsonb;date_today date:=(now() at time zone 'Asia/Riyadh')::date;u record;begin
 select id into cfo from public.profiles where role='CFO';select id into sup from public.profiles where role='Supervisor';select id into banker from public.profiles where role='BankAccountant';
 perform set_config('request.jwt.claim.sub',cfo::text,true);
 perform public.configure_daily_payment_mail('11111111-1111-4111-8111-111111111111','22222222-2222-4222-8222-222222222222',array['recipient@local.invalid'],'{}',true);
 update private.daily_payment_mail_config set dispatch_secret_hash=encode(extensions.digest('local-fixture-dispatch-secret','sha256'),'hex');
 insert into public.bank_accounts(company,bank_name,account_name,balance) values('LOCAL-MAIL','Bank','Operating',10000) returning id into account;
 insert into public.payments(company,beneficiary,amount,due_date,bank_account_id,supervisor_status,cfo_status,status,requested_by) values('LOCAL-MAIL','Executed approved',1250,date_today,account,'موافق','موافق','معتمد للدفع',banker) returning id into payment;
 perform set_config('request.jwt.claim.sub',banker::text,true);perform public.execute_payment(payment);
 insert into public.payments(company,beneficiary,amount,due_date,bank_account_id,supervisor_status,cfo_status,status,requested_by) values('LOCAL-MAIL','Approved not executed',3000,date_today,account,'موافق','موافق','معتمد للدفع',banker);
 insert into public.payments(company,beneficiary,amount,due_date,bank_account_id,supervisor_status,cfo_status,status,executed_at,requested_by) values('LOCAL-MAIL','Missing supervisor approval',4000,date_today,account,'معلق','موافق','منفذ',now(),banker);
 preview:=public.get_daily_payment_mail_preview(date_today);
 if jsonb_array_length(preview->'items')<>1 or (preview->>'total')::numeric<>1250 then raise exception 'MAIL_INCLUDED_UNAPPROVED_OR_UNEXECUTED';end if;
 begin perform public.claim_daily_payment_mail(date_today,preview->>'snapshot_hash',gen_random_uuid(),'wrong-secret');raise exception 'MAIL_CLIENT_CAN_CLAIM';exception when others then if sqlerrm<>'MAIL_SERVER_REQUIRED' then raise;end if;end;
 claim:=public.claim_daily_payment_mail(date_today,preview->>'snapshot_hash',gen_random_uuid(),'local-fixture-dispatch-secret');
 begin perform public.claim_daily_payment_mail(date_today,preview->>'snapshot_hash',gen_random_uuid(),'local-fixture-dispatch-secret');raise exception 'MAIL_CONCURRENT_SEND_ALLOWED';exception when others then if sqlerrm<>'MAIL_PREVIOUS_ATTEMPT_UNCERTAIN' then raise;end if;end;
 perform set_config('request.jwt.claim.sub',sup::text,true);
 begin perform public.finish_daily_payment_mail((claim->>'id')::uuid,'Accepted',null,null,'local-fixture-dispatch-secret');raise exception 'MAIL_OTHER_SENDER_FINISHED';exception when others then if sqlerrm<>'MAIL_DISPATCH_STATE_CONFLICT' then raise;end if;end;
 perform set_config('request.jwt.claim.sub',banker::text,true);
 perform public.finish_daily_payment_mail((claim->>'id')::uuid,'Accepted','fixture-provider-request',null,'local-fixture-dispatch-secret');
 duplicate:=public.claim_daily_payment_mail(date_today,preview->>'snapshot_hash',gen_random_uuid(),'local-fixture-dispatch-secret');
 if (duplicate->>'duplicate')::boolean is distinct from true or duplicate->>'id'<>claim->>'id' then raise exception 'MAIL_DUPLICATE_NOT_SUPPRESSED';end if;
 update public.payments set purpose='Updated approved purpose' where id=payment;preview:=public.get_daily_payment_mail_preview(date_today);
 claim:=public.claim_daily_payment_mail(date_today,preview->>'snapshot_hash',gen_random_uuid(),'local-fixture-dispatch-secret');
 perform public.finish_daily_payment_mail((claim->>'id')::uuid,'Unknown',null,'SEND_RESULT_UNCONFIRMED','local-fixture-dispatch-secret');
 begin perform public.claim_daily_payment_mail(date_today,preview->>'snapshot_hash',gen_random_uuid(),'local-fixture-dispatch-secret');raise exception 'MAIL_UNKNOWN_RETRIED';exception when others then if sqlerrm<>'MAIL_PREVIOUS_ATTEMPT_UNCERTAIN' then raise;end if;end;
 perform set_config('request.jwt.claim.sub',cfo::text,true);
 begin perform public.resolve_daily_payment_mail_attempt((claim->>'id')::uuid,false,'Verified with mailbox owner: no sent message found');raise exception 'MAIL_EARLY_RECONCILIATION';exception when others then if sqlerrm<>'MAIL_ATTEMPT_STILL_RECENT' then raise;end if;end;
 update public.daily_payment_mail_dispatches set updated_at=now()-interval '10 minutes' where id=(claim->>'id')::uuid;
 perform public.resolve_daily_payment_mail_attempt((claim->>'id')::uuid,false,'Verified with mailbox owner: no sent message found');
 perform set_config('request.jwt.claim.sub',banker::text,true);
 claim:=public.claim_daily_payment_mail(date_today,preview->>'snapshot_hash',gen_random_uuid(),'local-fixture-dispatch-secret');
 perform public.finish_daily_payment_mail((claim->>'id')::uuid,'Accepted','fixture-manual-retry',null,'local-fixture-dispatch-secret');
 for u in select id,role from public.profiles where active loop
  perform set_config('request.jwt.claim.sub',u.id::text,true);
  if u.role not in ('Supervisor','BankAccountant') then begin perform public.get_daily_payment_mail_preview(date_today);raise exception 'MAIL_PREVIEW_ROLE_ALLOWED';exception when others then if sqlerrm<>'MAIL_SENDER_ROLE_REQUIRED' then raise;end if;end;end if;
  if u.role<>'CFO' then begin perform public.configure_daily_payment_mail(null,null,'{}','{}',false);raise exception 'MAIL_CONFIG_ROLE_ALLOWED';exception when others then if sqlerrm<>'CFO_REQUIRED' then raise;end if;end;end if;
 end loop;
 if has_function_privilege('anon','public.claim_daily_payment_mail(date,text,uuid,text)','execute') or has_function_privilege('authenticated','private.verify_mail_dispatch_secret(text)','execute') then raise exception 'MAIL_DISPATCH_PRIVILEGE_LEAK';end if;
 if has_table_privilege('authenticated','private.daily_payment_mail_config','select') then raise exception 'MAIL_SECRET_CONFIG_EXPOSED';end if;
end$$;
select 'PASS: approved executed data only, sender/role enforcement, server-only claim, concurrent/duplicate/unknown suppression, changed-report revision, private credential and anonymous denial' as result;
